package net.civeira.phylax.common.infrastructure.migration;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.Duration;
import java.time.Instant;
import java.util.stream.Stream;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

@DisplayName("SQL dialects contract")
class SQLDialectsContractUnitTest {
  private static final String TABLE = "_migrations";
  private static final Duration WINDOW = Duration.ofMinutes(10);

  /** A dialect relying on every default of {@link SQLDialect}. */
  private static final SQLDialect DEFAULTS = new SQLDialect() {
    @Override
    public String createLogTable(String name) {
      return "CREATE TABLE " + name;
    }

    @Override
    public String createLockTable(String name) {
      return "CREATE TABLE " + name + "_lock";
    }

    @Override
    public String toString() {
      return "defaults";
    }
  };

  static Stream<SQLDialect> dialects() {
    return Stream.of(DEFAULTS, new H2Dialect(), new MySQLDialect(), new OracleDialect(),
        new PostgreSQLDialect(), new SQLServerDialect());
  }

  private static ResultSet lockRow(boolean locked, Instant granted) throws SQLException {
    ResultSet rs = mock(ResultSet.class);
    when(rs.getBoolean("locked")).thenReturn(locked);
    when(rs.getInt("locked")).thenReturn(locked ? 1 : 0);
    when(rs.getTimestamp("granted")).thenReturn(null == granted ? null : Timestamp.from(granted));
    return rs;
  }

  @ParameterizedTest(name = "{0}")
  @MethodSource("dialects")
  @DisplayName("Should build every statement against the given table")
  void shouldBuildStatements(SQLDialect dialect) {
    assertTrue(dialect.createLogTable(TABLE).contains(TABLE));
    assertTrue(dialect.createLockTable(TABLE).contains(TABLE));
    assertTrue(dialect.insertLock(TABLE).contains(TABLE));
    assertTrue(dialect.releaseLock(TABLE).startsWith("UPDATE " + TABLE));
    assertTrue(dialect.updateLock(TABLE).startsWith("UPDATE " + TABLE));
    assertTrue(dialect.selectLock(TABLE).contains("FROM " + TABLE));
    assertTrue(dialect.listExecutedSql(TABLE).contains("FROM " + TABLE));
  }

  @ParameterizedTest(name = "{0}")
  @MethodSource("dialects")
  @DisplayName("Should update existing log entries and insert new ones")
  void shouldMarkExistingAndNewEntries(SQLDialect dialect) {
    assertTrue(dialect.markOkSql(TABLE, true).startsWith("UPDATE " + TABLE));
    assertTrue(dialect.markOkSql(TABLE, false).startsWith("INSERT INTO " + TABLE));
    assertTrue(dialect.markFailSql(TABLE, true).startsWith("UPDATE " + TABLE));
    assertTrue(dialect.markFailSql(TABLE, false).startsWith("INSERT INTO " + TABLE));
  }

  @ParameterizedTest(name = "{0}")
  @MethodSource("dialects")
  @DisplayName("Should consider the lock active only while flagged and recently granted")
  void shouldInterpretLock(SQLDialect dialect) throws SQLException {
    Instant now = Instant.now();
    assertTrue(dialect.interpretLocked(lockRow(true, now), WINDOW));
    assertFalse(dialect.interpretLocked(lockRow(true, now.minus(Duration.ofHours(1))), WINDOW));
    assertFalse(dialect.interpretLocked(lockRow(true, null), WINDOW));
    assertFalse(dialect.interpretLocked(lockRow(false, now), WINDOW));
  }

  @Test
  @DisplayName("Seeds should run in the default order unless they say otherwise")
  void seedsShouldDefaultToOrderZero() {
    MigrationSeed seed = new MigrationSeed() {
      @Override
      public String id() {
        return "seed";
      }

      @Override
      public void run() {
        // nothing to seed
      }
    };
    assertEquals(0, seed.order());
  }
}
